[Proposition 7 of arXiv:2512.19517, 'Spiking and Resetting'] The process $({\bar X}^\varepsilon_t)_{t \ge 0}$ with state space $\{0,1\}$ and c\`adl\`ag  trajectories defined by 
\begin{equation}

\begin{split}
\forall t \ge 0, \quad {\bar X}^\varepsilon_t = \sum_{k\ge 0} {\mathbf 1}_{ t \in [e_{2k+1}^{\varepsilon}, e_{2k+2}^\varepsilon )} 
\end{split}
\end{equation}
converges in law to the jump Markov process $({\bar X}_t)_{t \ge 0}$ defined in Section \ref{sec:imr}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Theorem 6.1 in \cite{Adamczak_PTRF}) of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] In the case $1\le \alpha\le 2$, we have  for $r\ge 2$
\begin{align}
		\Big\Vert \sum_{i,j}a_{ij}\xi_{i}\tilde{\xi}_{j}\Big\Vert_{L_{r}}\asymp_{\alpha}&r^{1/2}\Vert A\Vert_{F}+r\Vert A\Vert_{l_{2}\to l_{2}}+r^{1/\alpha}\Vert A\Vert_{l_{\alpha^{*}}(l_{2})}\nonumber\\
		&+r^{(\alpha+2)/2\alpha}\Vert A\Vert_{l_{2}\to l_{\alpha^{*}}}+r^{2/\alpha}\Vert A\Vert_{l_{\alpha}\to l_{\alpha^{*}}},\nonumber
	\end{align}
    where $\Vert A\Vert_{l_{\alpha*}(l_2)}$ is defined in \eqref{matrix_norm}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 32 of arXiv:2507.06186, '2507.06186'] For every $\ka>0$,
there exists a constant $\th_\ka>0$ such that
for every $t\in(0,\th_\ka)$, the following holds:
\begin{align}

\lim_{\eps\to0}\mbf E\big[\msf T_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]
=\frac{\mr e^{\ka^2t\log t/2\pi}}{2\pi t}\int_D\mbf E\Big[\mbf 1_{\{\tau_D(B^{x,x}_t)>t\}}\mr e^{\ka^2\ga_t(B^{x,x}_t)}\Big]\d x;
\end{align}
\begin{align}

\lim_{\eps\to0}\mbf E\big[\msf M_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]
=\mr e^{\ka^2(t\log t-t)/2\pi}\int_D\mbf E\Big[\mbf 1_{\{\tau_D(B^x)>t\}}\mr e^{\ka^2\ga_t(B^x)}\Big]\d x;
\end{align}
\begin{multline}

\lim_{\eps\to0}\mbf{Var}\big[\msf T_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]=\frac{\mr e^{\ka^2t\log t/\pi}}{(2\pi t)^2}\int_{D^2}\mbf E\Bigg[\mbf 1_{\cap_{i\leq2}\{\tau_D({_i}B^{x_i,x_i}_t)>t\}}\\
\cdot\mr e^{\ka^2\sum_{i=1}^2\ga_t({_i}B^{x_i,x_i}_t)}\left(\mr e^{\ka^2\al_t({_1}B^{x_1,x_1}_t,{_2}B^{x_2,x_2}_t)}-1\right)\Bigg]\d x;
\end{multline}
\begin{multline}

\lim_{\eps\to0}\mbf{Var}\big[\msf M_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]=\mr e^{\ka^2(t\log t-t)/\pi}\int_{D^2}\mbf E\Bigg[\mbf 1_{\cap_{i\leq2}\{\tau_D({_i}B^{x_i})>t\}}\\
\cdot\mr e^{\ka^2\sum_{i=1}^2\ga_t({_i}B^{x_i})}\left(\mr e^{\ka^2\al_t({_1}B^{x_1},{_2}B^{x_2})}-1\right)\Bigg]\d x.
\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

The Fourier transform $f\mapsto\hat f$, $\hat f(\xi)=\int f(x)e^{-2\pi i x\cdot\xi}dx$, maps $\mathcal S(\mathbb R^d)$ continuously and bijectively onto itself, with continuous inverse given for every $x$ (pointwise, not just a.e.) by $f(x)=\int_{\mathbb R^d}\hat f(\xi)e^{2\pi i x\cdot\xi}d\xi$. Moreover $\hat{\hat f}(x)=f(-x)$, so the transform has order 4, and $\widehat{\partial^\beta f}=(2\pi i\xi)^\beta\hat f$, $\widehat{x^\alpha f}=(-2\pi i)^{-|\alpha|}\partial^\alpha\hat f$. Also $\int f\bar g=\int\hat f\,\overline{\hat g}$ on $\mathcal S$, which together with density gives the Plancherel theorem, and $\widehat{fg}=\hat f*\hat g$, $\widehat{f*g}=\hat f\hat g$ within $\mathcal S$.
f in the Schwartz space S(R^d)
convention e^{-2 pi i x.xi}

